from pathlib import Path
import json, html, hashlib

out=Path('output/auth-persistence-verification')
read=lambda f:json.loads((out/f).read_text(encoding='utf-8-sig'))
before=read('before-results.json');assert before['status']=='REPRODUCED' and not before['cloud'] and not before['errors']
assert before['before']['storageKind']=='localStorage' and before['after']['newTab']['storageKind']=='IndexedDB' and not before['after']['main']['authenticated']
unit=read('unit-results.json');assert unit['success'] and unit['numPassedTests']==676 and unit['numFailedTests']==0
sets=[('รุ่นที่สร้างใหม่','built-results.json'),('รุ่นพัฒนา','dev-results.json'),('อัปเกรดจากรุ่นเดิม','upgrade-results.json'),('สิทธิ์ฐานข้อมูลจริงในเครื่อง','access-results.json')]
rows=[];count=0
for label,file in sets:
    data=read(file);assert data['results'] and all(r['status']=='PASS' for r in data['results']);assert not data.get('cloud') and not data.get('errors');count+=len(data['results'])
    rows.extend(f'<tr><td>{label}</td><td>{html.escape(r["name"])}</td><td class="pass">PASS</td></tr>' for r in data['results'])
assert count==17
protected=read('protected-config.json');assert len(protected)==6 and all(p['unchanged'] for p in protected)
for p in protected:assert hashlib.sha256(Path(p['file']).read_bytes()).hexdigest()==p['sha256']
copies=[]
for name in ['firestore.rules','storage.rules']:
    data=Path(name).read_bytes();assert (Path('tmp/composer-backend')/name).read_bytes()==data
    copies.append({'file':name,'sha256':hashlib.sha256(data).hexdigest(),'identicalTestCopy':True})
(out/'rule-copy-checks.json').write_text(json.dumps(copies,indent=2),encoding='utf-8')
build=(out/'build.log').read_text(encoding='utf-8-sig');assert 'built in' in build
version=json.loads(Path('package.json').read_text())['version'];assert version=='0.44.0'
source=Path('src/data/firebase.ts').read_text();assert 'persistence:[browserLocalPersistence,indexedDBLocalPersistence]' in source and 'popupRedirectResolver:browserPopupRedirectResolver' in source
manifest={'version':version,'authSdk':json.loads(Path('node_modules/@firebase/auth/package.json').read_text())['version'],'backend':'demo-boq-v041','authPort':9899,'firestorePort':8380,'storagePort':9399,'devPort':5196,'compiledPort':5199,'upgradePort':5200,'unitTests':676,'unitFiles':len(unit['testResults']),'actualLocalPaths':count,'buildPassed':True,'sourceSha256':hashlib.sha256(Path('src/data/firebase.ts').read_bytes()).hexdigest(),'scope':'Local Chromium/email login only; no production/deployment or engineering acceptance.'}
(out/'provenance.json').write_text(json.dumps(manifest,indent=2),encoding='utf-8')
images=[('ก่อนแก้: เปิดแท็บใหม่แล้วแท็บเดิมออกจากระบบเอง','before-main-unexpected-signout.png'),('หลังแก้: เปิดอีกแท็บแล้วบัญชีและฟอร์มราคาเดิมยังอยู่','built-open-tab-preserves-quote.png'),('เปลี่ยนเป็น Viewer: ฟอร์มราคาและโครงการส่วนตัวหายไป','built-viewer-quote-cleared.png'),('Viewer ดูราคาได้ แต่ปุ่มแก้ไขถูกปิด','built-viewer-readonly.png'),('ก่อนสลับบัญชีซ้ำ: ผู้ดูแลเปิดฟอร์มสำเนา','built-admin-copy-before.png'),('หลังสลับบัญชีซ้ำ: ฟอร์มสำเนาส่วนตัวถูกล้าง','built-viewer-copy-cleared.png'),('อัปเกรดจากรุ่นเดิม: บัญชีเดิมเปิดต่อได้','upgrade-restored-account.png'),('หลังออกจากระบบ: รุ่นเดิมไม่คืนบัญชีเก่า','upgrade-logout-no-old-session.png')]
for _,name in images:assert (out/name).is_file()
gallery=''.join(f'<figure><figcaption>{html.escape(label)}</figcaption><a href="{name}"><img src="{name}" alt="{html.escape(label)}" loading="eager"></a></figure>' for label,name in images)
requirement_lines=[line for line in Path('docs/CURRENT_REQUIREMENTS_STATUS.md').read_text().splitlines() if line.startswith('| ') and line.split('|')[1].strip().isdigit()]
assert len(requirement_lines)==12
requirement_rows=''.join('<tr>'+''.join('<td>'+html.escape(c.strip())+'</td>' for c in line.split('|')[1:-1])+'</tr>' for line in requirement_lines)
protected_rows=''.join(f'<tr><td>{html.escape(p["file"])}</td><td class="pass">SHA-256 เท่าเดิม</td></tr>' for p in protected)
links=''.join(f'<li><a href="{f}">{html.escape(label)}</a></li>' for label,f in [('อาการก่อนแก้','before-results.json'),('ทดสอบรุ่นสร้างใหม่','built-results.json'),('ทดสอบรุ่นพัฒนา','dev-results.json'),('ทดสอบอัปเกรด','upgrade-results.json'),('ทดสอบสิทธิ์','access-results.json'),('Unit tests เดิม','unit-results.json'),('Build log','build.log'),('ตรวจไฟล์ที่คงไว้','protected-config.json'),('ตรวจ Rules ชุดจำลอง','rule-copy-checks.json'),('ที่มาชุดทดสอบ','provenance.json')])
doc=f'''<!doctype html><html lang="th"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BOQ/BBS v0.44 — ตรวจการใช้บัญชีหลายแท็บ</title>
<style>*{{box-sizing:border-box}}body{{margin:0;background:#f2f6f4;color:#203b43;font:16px/1.65 Tahoma,"Segoe UI",sans-serif}}main{{max-width:1180px;padding:32px 24px;margin:auto}}h1{{font-size:32px;line-height:1.4}}h2{{font-size:23px}}h3{{font-size:18px}}section,.notice{{background:white;border:1px solid #d5e2de;border-radius:12px;padding:22px;margin:22px 0}}.notice{{border-left:5px solid #b87818}}.stats{{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}}.stats div{{background:#1d3b43;color:white;border-radius:12px;padding:18px}}.stats b{{font-size:30px;display:block}}a{{color:#096c5c;overflow-wrap:anywhere}}.pass{{color:#096c5c;font-weight:bold}}.scroll{{overflow-x:auto}}table{{width:100%;border-collapse:collapse;font-size:14px}}th,td{{text-align:left;padding:12px;vertical-align:top;border-bottom:1px solid #e0e9e5;overflow-wrap:anywhere}}th{{background:#edf3f0}}.gallery{{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}}figure{{margin:0;border:1px solid #dae6e0;border-radius:8px;padding:12px}}figcaption{{min-height:52px;font-size:14px}}img{{width:100%;height:330px;object-fit:contain;background:#f1f5f3}}code{{overflow-wrap:anywhere}}summary{{cursor:pointer}}li{{margin:8px 0}}.muted{{color:#607d83;font-size:14px}}@media(max-width:680px){{main{{padding:18px 12px}}h1{{font-size:25px}}section,.notice{{padding:16px}}.stats,.gallery{{grid-template-columns:1fr}}img{{height:280px}}}}</style>
<main><p class="muted">BOQ &amp; BBS · v0.44 · 13 ตุลาคม 2026 · ตรวจในเครื่อง</p><h1>แก้เปิดหลายแท็บแล้วหลุดบัญชี — ผ่านเฉพาะชุดทดสอบนี้</h1>
<p>แก้การเริ่มต้นบัญชีให้ใช้วิธีเก็บสถานะตรงกับตอนเข้าสู่ระบบ เปิดแท็บใหม่ได้โดยแท็บเดิมยังอยู่ในบัญชีเดิม เมื่อสลับเป็น Viewer ข้อมูลราคาและสำเนาของโครงการส่วนตัวถูกล้าง และยังใช้สิทธิ์แยกโครงการตามเดิม</p>
<div class="stats"><div><b>676</b>Unit tests เดิมผ่าน</div><div><b>17</b>เส้นทางจริงในระบบจำลองผ่าน</div><div><b>6</b>ไฟล์ Rules/ตั้งค่า/Auth เท่าเดิม</div></div>
<div class="notice"><strong>ยังไม่ใช่การตรวจรับระบบเต็มหรือ BBS ใช้ก่อสร้าง</strong><p>ยังรอชุดกรณีวิศวกรรมที่รับรอง การเทียบแบบ GULF และตำแหน่งเหล็กจริง การยอมรับแบบโดยเจ้าของงาน และการตรวจระบบ Production กับ Rules ที่คุณกำหนดและ deploy เอง รอบนี้ไม่มีการแก้หรือ deploy Rules/Hosting และไม่เพิ่ม Cloud Functions</p></div>
<section><h2>ปัญหาที่พบและผลหลังแก้</h2><p>ทดสอบรุ่น v0.43 ที่สร้างไว้จริง: เข้าสู่ระบบในแท็บแรกโดยใช้ localStorage จากนั้นเปิดแท็บที่สอง พบว่าแท็บใหม่ย้ายบัญชีไป IndexedDB และแท็บแรกออกจากระบบเอง ตรงกับลำดับการเลือกและย้ายที่เก็บข้อมูลใน Firebase SDK ที่ติดตั้งอยู่</p><p>v0.44 เลือก localStorage ก่อนตั้งแต่เริ่มแอป และยังรองรับ IndexedDB เป็นเส้นทางย้ายบัญชีรุ่นเดิมเข้าสู่ที่เก็บที่เลือกก่อน ไม่คัดลอก token เอง ไม่จำลอง Auth หรือส่งเหตุการณ์ข้ามแท็บเอง การกำหนดการเริ่มต้นและตัวช่วย Google popup อ้างอิง <a href="https://firebase.google.com/docs/auth/web/custom-dependencies">เอกสารหลักของ Firebase</a>; การคงบัญชีบนโดเมนเดียวกันอ้างอิง <a href="https://firebase.google.com/docs/auth/web/auth-state-persistence">คู่มือ Persistence</a></p><p><strong>ตอนนำรุ่นใหม่ไปใช้ ให้ปิดหรือโหลดใหม่ทุกแท็บของแอปรุ่นเก่าบนโดเมนเดียวกัน</strong> เพื่อให้ทุกแท็บเริ่มบัญชีด้วยการตั้งค่าชุดเดียวกัน การเปิดรุ่นเก่าและรุ่นใหม่พร้อมกันยังไม่อยู่ในขอบเขตตรวจรับ</p></section>
<section><h2>หลักฐานจากหน้าจอจริง</h2><p class="muted">คลิกภาพเพื่อเปิดเต็มขนาด ข้อมูลในภาพเป็นโครงการและราคาสังเคราะห์สำหรับทดสอบ ไม่ใช่ราคา/แบบที่รับรอง</p><div class="gallery">{gallery}</div></section>
<section><h2>ตรวจอะไรแล้ว</h2><div class="scroll"><table><thead><tr><th>ชุดตรวจ</th><th>กรณี</th><th>ผล</th></tr></thead><tbody>{''.join(rows)}</tbody></table></div><p>Build และตรวจชนิดข้อมูลผ่าน Unit tests เดิม {len(unit['testResults'])} ไฟล์ / 676 กรณีผ่าน ไม่เพิ่มกรณีเทียมเพื่อเพิ่มจำนวนผลทดสอบ</p><p class="muted">การรัน UI ครั้งแรกหา Project card ขณะยังอยู่หน้า BOQ จึงไม่ผ่านขั้นนำทาง แก้ตัวทดสอบให้ใช้ปุ่มเลือกโครงการจริง แล้วทดสอบซ้ำครบ บันทึกครั้งแรกยังอยู่ใน built-first-run.json / dev-first-run.json; ไม่ใช่ปัญหาข้อมูลข้ามบัญชี</p></section>
<section><h2>ไฟล์ที่คงไว้</h2><div class="scroll"><table><thead><tr><th>ไฟล์</th><th>ผลเทียบก่อน–หลัง</th></tr></thead><tbody>{protected_rows}</tbody></table></div><p>แก้การเริ่มต้นใน src/data/firebase.ts พร้อมป้ายรุ่น/เลขรุ่นและเอกสารประกอบ ไม่มีการเปลี่ยนสูตรปริมาณ BOQ/BBS หรือสถานะรับรองวิศวกรรม Rules ชุดทดสอบเป็นสำเนาที่เนื้อหาเท่ากับไฟล์เดิมทุกไบต์</p></section>
<section><h2>ขอบเขตและงานที่ยังค้าง</h2><ul><li>ใช้ Chromium และการเข้าสู่ระบบด้วยอีเมลใน Firebase จำลอง demo-boq-v041 เท่านั้น ไม่มีการเรียกข้อมูล Production</li><li>ทดสอบอัปเกรดด้วยไฟล์รุ่น v0.43/v0.44 จริงบนที่อยู่เดียวกัน โดยปิดแท็บเก่าทั้งหมดก่อนเปลี่ยนรุ่น ไม่สร้างข้อมูลบัญชีลง browser storage เอง</li><li>ยังไม่ตรวจเบราว์เซอร์อื่น Google OAuth จริง อุปกรณ์ที่ปิดกั้น storage การทำงานออฟไลน์/คำสั่งที่เข้าคิว และการเปิดหลายรุ่นพร้อมกัน</li><li>รอบนี้ไม่ได้ส่งออก Excel/PDF ใหม่ หลักฐานส่งออกจริงของ v0.43 ยังคงอยู่ใน <a href="../priced-boq-verification/DEVELOPMENT_REPORT.html">รายงานราคา BOQ</a> และมีขอบเขตเดิม ไม่ถือว่าได้ตรวจซ้ำในรอบนี้</li><li>มาตรฐานเริ่มต้น BS8666 ที่มีอยู่ยังเป็นฐานเดิม ต้องรับรอง ACI/ข้อกำหนดโครงการและกรณีอ้างอิงจริง; code33 ยังไม่รองรับ และการปิดรูปจริง code51 ยังรอตรวจ</li></ul><details><summary>สถานะข้อกำหนดเดิมทั้ง 12 ข้อ</summary><div class="scroll"><table><thead><tr><th>#</th><th>ข้อกำหนด</th><th>ส่วนที่มีแล้ว</th><th>รอตรวจรับ</th></tr></thead><tbody>{requirement_rows}</tbody></table></div></details></section>
<section><h2>ไฟล์หลักฐานและเอกสาร</h2><ul>{links}<li><a href="../../docs/AUTHENTICATION_SETUP.md">เอกสารบัญชีและการอัปเกรด</a></li><li><a href="../../docs/CURRENT_REQUIREMENTS_STATUS.md">สถานะข้อกำหนดเดิม</a></li></ul></section></main></html>'''
(out/'DEVELOPMENT_REPORT.html').write_text(doc,encoding='utf-8')
print(f'Written scoped v0.44 report: {count} actual local paths,676 existing unit tests,{len(images)} actual UI images; full acceptance remains pending')
